import { useAppForm } from '@/hooks/form'
import { z } from 'zod'

// 유효성 스키마
const SignUpForm = z.object({
  email: z.string().email('Invalid email'),
  password: z.string().min(8, 'At least 8 chars'),
  confirmPassword: z.string(),
})

export default function SignUp() {
  const form = useAppForm({
    defaultValues: { email: '', password: '', confirmPassword: '' },
    validators: { onChange: SignUpForm },
    onSubmit: async ({ value }) => {
      console.log('✅ 최종 제출 값:', value)
    },
  })

  return (
    <formonSubmit={(e) => {
        e.preventDefault()
        void form.handleSubmit()
      }}
    >
      {/* Email Field */}
      <form.AppField name="email">
        {(field) => <field.Input placeholder="Email" />}
      </form.AppField>

      {/* Password Field */}
      <form.AppField name="password">
        {(field) => <field.Input placeholder="Password" type="password" />}
      </form.AppField>

      {/* Confirm Password Field */}
      <form.AppFieldname="confirmPassword"
        validators={{
          onChange: ({ value, fieldApi }) => {
            if (value !== fieldApi.form.getFieldValue('password'))
              return { message: 'Password does not match' }
            return undefined
          },
        }}
      >
        {(field) => <field.Input placeholder="Confirm password" type="password" />}
      </form.AppField>

      {/* Submit */}
      <form.AppForm>
        <form.Button type="submit" className="pri">
          Sign up
        </form.Button>
      </form.AppForm>
    </form>
  )
}

